arguments.command:
cat << 'PYEOF' > /tmp/gen_report.py
import json

with open('/tmp/analysis_results.json') as f:
    r = json.load(f)

# Helper: sanitize data — filter to main 3 brands for most analyses, handle Samsung Estados Unidos outlier
# Samsung "Estados Unidos" has med=$25349.5 with n=2 — clearly an outlier/data quality issue, note it but exclude from arbitrage

# Generate HTML
html = '''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Smartwatch Secondary Market Analysis — Q1 2026</title>
<style>
:root {
  --bg: #0f1117;
  --surface: #1a1d27;
  --surface2: #22262f;
  --border: #2d3140;
  --text: #e4e7f0;
  --text-muted: #8b90a0;
  --accent: #6c8cff;
  --accent2: #40c4aa;
  --accent3: #ff7a5c;
  --accent4: #ffd166;
  --green: #40c4aa;
  --red: #ff5c6c;
  --apple: #6c8cff;
  --garmin: #40c4aa;
  --samsung: #ff7a5c;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 32px; }
header {
  padding: 60px 0 40px;
  border-bottom: 1px solid var(--border);
}
header h1 {
  font-size: 2.2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
header .subtitle {
  color: var(--text-muted);
  font-size: 1.05rem;
}
header .meta {
  margin-top: 16px;
  display: flex;
  gap: 24px;
  color: var(--text-muted);
  font-size: 0.85rem;
}
.kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin: 32px 0;
}
.kpi-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px 24px;
}
.kpi-card .label {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 4px;
}
.kpi-card .value {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.kpi-card .note {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 4px;
}
section {
  padding: 48px 0;
  border-bottom: 1px solid var(--border);
}
section:last-child { border-bottom: none; }
h2 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}
h3 {
  font-size: 1.15rem;
  font-weight: 600;
  margin: 28px 0 12px;
  color: var(--accent);
}
p { margin-bottom: 16px; color: var(--text); font-size: 0.95rem; }
.insight {
  background: var(--surface);
  border-left: 3px solid var(--accent);
  padding: 16px 20px;
  border-radius: 0 8px 8px 0;
  margin: 20px 0;
  font-size: 0.92rem;
}
.insight strong { color: var(--accent); }
table {
  width: 100%;
  border-collapse: collapse;
  margin: 16px 0;
  font-size: 0.88rem;
}
th {
  text-align: left;
  padding: 10px 14px;
  background: var(--surface);
  border-bottom: 2px solid var(--border);
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
}
td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
}
tr:hover td { background: var(--surface); }
.chart-container {
  margin: 24px 0;
  background: var(--surface);
  border-radius: 12px;
  padding: 24px;
  border: 1px solid var(--border);
}
.chart-title {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  margin-bottom: 16px;
}
svg text { font-family: 'Inter', -apple-system, sans-serif; }
.bar-label { fill: var(--text-muted); font-size: 12px; }
.bar-value { fill: var(--text); font-size: 12px; font-weight: 600; }
.pill {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 12px;
  font-size: 0.78rem;
  font-weight: 600;
}
.pill-apple { background: rgba(108,140,255,0.15); color: var(--apple); }
.pill-garmin { background: rgba(64,196,170,0.15); color: var(--garmin); }
.pill-samsung { background: rgba(255,122,92,0.15); color: var(--samsung); }
.pos { color: var(--green); }
.neg { color: var(--red); }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
@media (max-width: 768px) { .grid-2 { grid-template-columns: 1fr; } }
.rec-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin: 16px 0;
}
.rec-card h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--accent2);
}
.rec-card p { margin-bottom: 0; }
.heatmap-cell {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.82rem;
  font-weight: 600;
  min-width: 60px;
  text-align: center;
}
.toc { margin: 24px 0; }
.toc a {
  color: var(--accent);
  text-decoration: none;
  display: block;
  padding: 4px 0;
  font-size: 0.92rem;
}
.toc a:hover { text-decoration: underline; }
</style>
</head>
<body>
<div class="container">

<header>
  <h1>Global Smartwatch Secondary Market Analysis</h1>
  <p class="subtitle">Q1 2026 — Pricing dynamics, geographic arbitrage, and seller behavior across 3,607 resale listings</p>
  <div class="meta">
    <span>Dataset: 3,607 listings</span>
    <span>Brands: Apple, Garmin, Samsung</span>
    <span>Sellers: 1,754 unique</span>
    <span>Countries: 27 markets</span>
  </div>
</header>

<nav class="toc">
  <a href="#kpis">Key Performance Indicators</a>
  <a href="#overview">1. Market Overview &amp; Listing Composition</a>
  <a href="#brand-pricing">2. Brand-Level Pricing &amp; Value Retention</a>
  <a href="#geo-pricing">3. Geographic Pricing Arbitrage</a>
  <a href="#case-size">4. Case Size &amp; Price Premium Analysis</a>
  <a href="#sellers">5. Power Seller Behavior &amp; Pricing Patterns</a>
  <a href="#recommendations">6. Strategic Recommendations</a>
</nav>
'''

# ===== KPI SECTION =====
apple_stats = r['brand_price_stats']['Apple']
garmin_stats = r['brand_price_stats']['Garmin']
samsung_stats = r['brand_price_stats']['Samsung']

html += f'''
<section id="kpis">
<h2>Key Performance Indicators</h2>
<div class="kpi-row">
  <div class="kpi-card">
    <div class="label">Median Price — Apple</div>
    <div class="value" style="color:var(--apple)">${apple_stats['median']:.0f}</div>
    <div class="note">Mean: ${apple_stats['mean']:.0f} | IQR: ${apple_stats['q1']:.0f}–${apple_stats['q3']:.0f}</div>
  </div>
  <div class="kpi-card">
    <div class="label">Median Price — Garmin</div>
    <div class="value" style="color:var(--garmin)">${garmin_stats['median']:.0f}</div>
    <div class="note">Mean: ${garmin_stats['mean']:.0f} | IQR: ${garmin_stats['q1']:.0f}–${garmin_stats['q3']:.0f}</div>
  </div>
  <div class="kpi-card">
    <div class="label">Median Price — Samsung</div>
    <div class="value" style="color:var(--samsung)">${samsung_stats['median']:.0f}</div>
    <div class="note">Mean: ${samsung_stats['mean']:.0f} | IQR: ${samsung_stats['q1']:.0f}–${samsung_stats['q3']:.0f}</div>
  </div>
  <div class="kpi-card">
    <div class="label">New vs Used Premium (Apple)</div>
    <div class="value" style="color:var(--accent4)">+{r['new_used_premium']['Apple']['premium_pct']}%</div>
    <div class="note">New: ${r['new_used_premium']['Apple']['new_median']:.0f} vs Used: ${r['new_used_premium']['Apple']['used_median']:.0f}</div>
  </div>
  <div class="kpi-card">
    <div class="label">Geographic Price Spread — Garmin</div>
    <div class="value" style="color:var(--green)">${r['geo_spread']['Garmin']['spread']:.0f}</div>
    <div class="note">{r['geo_spread']['Garmin']['min_country']}: ${r['geo_spread']['Garmin']['min_median']:.0f} → {r['geo_spread']['Garmin']['max_country']}: ${r['geo_spread']['Garmin']['max_median']:.0f}</div>
  </div>
  <div class="kpi-card">
    <div class="label">Case Size – Price Correlation</div>
    <div class="value">{r['case_size_corr']}</div>
    <div class="note">Weak positive — size alone doesn't drive price</div>
  </div>
  <div class="kpi-card">
    <div class="label">Power Seller Concentration</div>
    <div class="value">{r['power_seller_listing_pct']}%</div>
    <div class="note">{r['power_seller_count']} sellers (top 5%) control nearly half of listings</div>
  </div>
</div>
</section>
'''

# ===== SECTION 1: MARKET OVERVIEW =====
brand_counts = r['brand_counts']
brand_pcts = r['brand_pcts']
# Bar chart for brand distribution
brand_data = [('Apple', brand_counts.get('Apple',0), '#6c8cff'),
              ('Garmin', brand_counts.get('Garmin',0), '#40c4aa'),
              ('Samsung', brand_counts.get('Samsung',0), '#ff7a5c')]
max_brand = max(b[1] for b in brand_data)

brand_bars = ''
for i, (name, count, color) in enumerate(brand_data):
    y = 30 + i * 50
    w = count / max_brand * 500
    pct = brand_pcts.get(name, 0)
    brand_bars += f'''
    <rect x="100" y="{y}" width="{w}" height="32" fill="{color}" rx="4" opacity="0.85"/>
    <text x="90" y="{y+21}" text-anchor="end" class="bar-label">{name}</text>
    <text x="{105+w}" y="{y+21}" class="bar-value">{count:,} ({pct}%)</text>'''

# Condition distribution
cond_counts = r['condition_counts']
cond_main = {'New': cond_counts.get('New',0), 'Used': cond_counts.get('Used',0),
             'Open Box': cond_counts.get('Open box',0), 'Refurbished': sum(v for k,v in cond_counts.items() if 'Refurb' in k)}
cond_main['Other'] = r['total_listings'] - sum(cond_main.values())
cond_colors = {'New':'#40c4aa','Used':'#6c8cff','Open Box':'#ff7a5c','Refurbished':'#ffd166','Other':'#8b90a0'}

cond_bars = ''
max_cond = max(cond_main.values())
ci = 0
for name, count in sorted(cond_main.items(), key=lambda x: -x[1]):
    if count == 0: continue
    y = 30 + ci * 42
    w = count / max_cond * 450
    pct = round(count/r['total_listings']*100, 1)
    cond_bars += f'''
    <rect x="140" y="{y}" width="{w}" height="28" fill="{cond_colors.get(name,'#888')}" rx="4" opacity="0.85"/>
    <text x="130" y="{y+19}" text-anchor="end" class="bar-label">{name}</text>
    <text x="{148+w}" y="{y+19}" class="bar-value">{count:,} ({pct}%)</text>'''
    ci += 1

# Top countries
country_data = sorted(r['country_counts'].items(), key=lambda x: -x[1])[:10]
max_country = country_data[0][1]
country_bars = ''
for i, (name, count) in enumerate(country_data):
    y = 30 + i * 38
    w = count / max_country * 450
    pct = r['country_pcts'].get(name, 0)
    country_bars += f'''
    <rect x="140" y="{y}" width="{w}" height="26" fill="#6c8cff" rx="3" opacity="0.7"/>
    <text x="130" y="{y+18}" text-anchor="end" class="bar-label">{name}</text>
    <text x="{148+w}" y="{y+18}" class="bar-value">{count:,} ({pct}%)</text>'''

html += f'''
<section id="overview">
<h2>1. Market Overview &amp; Listing Composition</h2>
<p>The dataset captures <strong>3,607 active listings</strong> from <strong>1,754 unique sellers</strong> across <strong>27 countries</strong>. Apple dominates by volume with nearly two-thirds of all listings, followed by Garmin at 20.7% and Samsung at 13.0%. The overall median listing price is <strong>${r['price_overall_median']:.0f}</strong>, with significant variance across brands and conditions.</p>

<div class="grid-2">
<div class="chart-container">
  <div class="chart-title">Listings by Brand</div>
  <svg width="100%" viewBox="0 0 700 190" xmlns="http://www.w3.org/2000/svg">
    {brand_bars}
  </svg>
</div>
<div class="chart-container">
  <div class="chart-title">Listings by Condition</div>
  <svg width="100%" viewBox="0 0 700 {30 + ci*42 + 10}" xmlns="http://www.w3.org/2000/svg">
    {cond_bars}
  </svg>
</div>
</div>

<div class="chart-container">
  <div class="chart-title">Top 10 Countries by Listing Volume</div>
  <svg width="100%" viewBox="0 0 700 {30 + 10*38 + 10}" xmlns="http://www.w3.org/2000/svg">
    {country_bars}
  </svg>
</div>

<div class="insight">
  <strong>Key takeaway:</strong> The US accounts for 65% of listings, making it the primary market. The UK is a distant second at 13%. Worldwide shipping is offered on {r['worldwide_shipping_pct']}% of listings — notably, Garmin ({r['worldwide_shipping_by_brand']['Garmin']}%) and Samsung ({r['worldwide_shipping_by_brand']['Samsung']}%) sellers are far more likely to ship globally than Apple sellers ({r['worldwide_shipping_by_brand']['Apple']}%), creating barriers to cross-border Apple arbitrage. New items make up {r['condition_pcts'].get('New',0)}% of listings, suggesting the secondary market includes substantial retail arbitrage and liquidation activity alongside genuine used-item resale.
</div>
</section>
'''

# ===== SECTION 2: BRAND PRICING =====
# Box-plot style horizontal chart
brands_ordered = ['Apple', 'Garmin', 'Samsung']
brand_colors = {'Apple':'#6c8cff','Garmin':'#40c4aa','Samsung':'#ff7a5c'}

# Use a reasonable max for chart scale (cap at $1500 to show detail)
chart_max = 1500

box_elements = ''
for i, brand in enumerate(brands_ordered):
    s = r['brand_price_stats'][brand]
    y = 40 + i * 70
    # Scale function
    def sx(val):
        return 120 + min(val, chart_max) / chart_max * 520
    # Whiskers (min to q1, q3 to max capped)
    x_min = sx(max(s['min'], 70))
    x_q1 = sx(s['q1'])
    x_med = sx(s['median'])
    x_q3 = sx(s['q3'])
    x_max = sx(min(s['max'], chart_max))
    color = brand_colors[brand]
    box_elements += f'''
    <text x="110" y="{y+20}" text-anchor="end" class="bar-label" font-weight="600">{brand}</text>
    <line x1="{x_min}" y1="{y+16}" x2="{x_q1}" y2="{y+16}" stroke="{color}" stroke-width="2" opacity="0.6"/>
    <line x1="{x_min}" y1="{y+8}" x2="{x_min}" y2="{y+24}" stroke="{color}" stroke-width="2" opacity="0.6"/>
    <rect x="{x_q1}" y="{y+2}" width="{x_q3-x_q1}" height="28" fill="{color}" rx="4" opacity="0.3" stroke="{color}" stroke-width="1.5"/>
    <line x1="{x_med}" y1="{y+2}" x2="{x_med}" y2="{y+30}" stroke="{color}" stroke-width="3"/>
    <line x1="{x_q3}" y1="{y+16}" x2="{x_max}" y2="{y+16}" stroke="{color}" stroke-width="2" opacity="0.6"/>
    <line x1="{x_max}" y1="{y+8}" x2="{x_max}" y2="{y+24}" stroke="{color}" stroke-width="2" opacity="0.6"/>
    <text x="{x_med}" y="{y-2}" text-anchor="middle" fill="{color}" font-size="11" font-weight="700">${s['median']:.0f}</text>'''

# Axis labels
axis_ticks = ''
for val in [0, 250, 500, 750, 1000, 1250, 1500]:
    x = 120 + val / chart_max * 520
    axis_ticks += f'''
    <line x1="{x}" y1="25" x2="{x}" y2="{40 + 3*70 - 30}" stroke="var(--border)" stroke-width="1" stroke-dasharray="3"/>
    <text x="{x}" y="{40 + 3*70 - 15}" text-anchor="middle" fill="#8b90a0" font-size="10">${val}</text>'''

# Condition premium table
premium_rows = ''
for brand in brands_ordered:
    nup = r['new_used_premium'].get(brand, {})
    prem = nup.get('premium_pct', 'N/A')
    prem_class = 'pos' if isinstance(prem, (int,float)) and prem > 0 else 'neg'
