    size_brand_rows += f'<tr><td style="font-weight:600">{sbin}</td>{cells}</tr>'

html += f'''
<section id="case-size">
<h2>4. Case Size &amp; Price Premium Analysis</h2>
<p>Case size data is available for <strong>{r['case_size_available']:,}</strong> of 3,607 listings ({100-r['case_size_missing_pct']:.0f}% coverage). The overall correlation between case size and price is <strong>{r['case_size_corr']}</strong> — weak, indicating that case size alone is not a strong price predictor. However, binned analysis reveals a meaningful premium at the 49mm+ tier.</p>

<div class="chart-container">
